#include <iostream>

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    if (n < 0) n = -n;

    int digits{};
    int sum{};

    do
    {
        sum += n % 10;
        ++digits;
        n /= 10;
    } while (n != 0);

    std::cout << "digits " << digits << "\n";
    std::cout << "sum " << sum << "\n";

    return 0;
}
